    senet_throw_sticks: "棒を投げる",
    senet_rules_title: "セネトのルール",
    senet_rules_intro: "PaperGamesでのセネトの遊び方を簡単にまとめました。もともとのルールが失われてしまったゲームを現代に再構成したものなので、これを唯一の正解ではなく、一つの解釈として捉えてください。",
    senet_rules_basics_title: "基本的な考え方",
    senet_term_pieces: "駒とコース",
    senet_rules_pieces: "各プレイヤーは5個の駒を持ち、30マスのコースを進みます。マス番号は「牛耕式（ボウストロフェドン）」と呼ばれる順路で振られていて、一番上の列は左から右へ、真ん中の列は右から左へ、一番下の列はまた左から右へと続きます。手番では棒を投げ、出た目の数だけ自分の駒を1つ前進させます。",
    senet_term_sticks: "棒を投げる",
    senet_rules_sticks: "サイコロの代わりに、両面のある投げ棒を4本使います。出目は表を向いた棒の本数で決まりますが、1本も表にならなかった場合は0ではなく最高の結果である6として扱われます。1、4、6のいずれかが出ると、もう一度手番を得られます。",
    senet_term_stacking: "重ねと捕獲",
    senet_rules_stacking: "自分の駒どうしは同じマスに重ねて置くことができ、その場合その駒は保護され、相手はそこに乗ることができません。単独で立っている駒は捕獲の対象になり、相手の駒がそこに乗ると単純に位置を入れ替えられてしまいます。",
    senet_term_houses: "3つの特別なマス",
    senet_rules_houses: "15番目のマス「再生の家」は、そこにいる駒にとって常に安全です。26番目のマス「美の家」は飛び越えることができず、駒は必ずそこにぴったり止まってから先へ進まなければなりません。27番目のマス「水の家」は危険なマスで、そこに止まった駒は即座に「再生の家」（そこがふさがっていれば1番目のマス）まで押し戻されてしまいます。",
    senet_rules_end_title: "ゲームの終わり方",
    senet_term_win: "勝利条件",
    senet_rules_win: "駒をコースの外に出すには、ちょうどぴったりの出目が必要です。5個すべての駒を先に上げたプレイヤーの勝ちです。",
    senet_term_resignation: "投了",
    senet_rules_resignation: "プレイヤーはいつでも投了でき、その時点で相手の勝ちとなり対局が終了します。",
    shogi_promote_question: "この駒を成りますか?",
    shogi_promote_yes: "成る",
    shogi_promote_no: "成らない",
    shogi_rules_title: "将棋のルール",
    shogi_rules_intro: "PaperGamesでの将棋の遊び方を簡単にまとめました。国際チェスに慣れている方には、いくつか異なる考え方があるので参考にしてください。",
    shogi_rules_basics_title: "基本的な考え方",
    shogi_term_board: "盤と駒",
    shogi_rules_board: "各陣営は9×9の盤上に20枚の駒を持ちます。玉将1枚、飛車1枚、角行1枚、金将2枚、銀将2枚、桂馬2枚、香車2枚、そして歩兵9枚です。駒はシンプルな五角形で、相手側を指し示す向きによってどちらの陣営の駒かが決まり、色では区別されません。先手（黒）が常に最初に指します。",
    shogi_term_promotion: "成り",
    shogi_rules_promotion: "玉将と金将を除くすべての駒は、盤の敵陣側3段に入る、そこから出る、またはその中で動くことで、より強い駒に成ることができます。成るかどうかは基本的に任意ですが、歩兵や香車が一番奥の段に到達する場合、桂馬が奥の2段のいずれかに到達する場合は、成らないとその駒が二度と動けなくなってしまうため、強制的に成ります。",
    shogi_term_drops: "持ち駒と打つ",
    shogi_rules_drops: "駒を取ってもその駒がゲームから消えることはありません。取った駒は持ち主が入れ替わり、成っていた場合は成る前の形に戻って、取った側の持ち駒になります。以降の手番では、盤上の駒を動かす代わりに、持ち駒を空いているマスへ「打つ」ことができます。これは将棋を象徴する仕組みの一つで、対局が駒不足で行き詰まることがほとんどない理由でもあります。",
    shogi_term_drop_limits: "打つ際の制限",
    shogi_rules_drop_limits: "歩兵や香車は一番奥の段には打てず、桂馬は奥の2段のいずれにも打てません。そこに打っても、その駒は二度と動けなくなってしまうからです。また、すでに成っていない自分の歩兵がある筋には歩兵を打てません（二歩）。さらに、歩兵を打つことで直接チェックメイトにすることは禁止されています（打ち歩詰め。チェックをかけること自体は問題ありません）。",
    shogi_rules_end_title: "ゲームの終わり方",
    shogi_term_win: "勝利条件",
    shogi_rules_win: "チェックされている玉将が、逃げることも、合駒で防ぐことも、王手をかけている駒を取ることもできない場合、チェックメイトとなりゲームは即座に終了します。",
    shogi_term_resignation: "投了",
    shogi_rules_resignation: "プレイヤーはいつでも投了でき、その時点で相手の勝ちとなり対局が終了します。",
    shogi_term_sennichite: "千日手",
    shogi_rules_sennichite: "同じ局面(盤上の駒の配置、双方の持ち駒、手番がすべて同じ)が4回現れた場合、引き分けになります。ただし、その間ずっと一方が毎手王手をかけ続けていた場合(連続王手の千日手)は、王手をかけていた側の負けになります。PaperGamesはこのルールを自動的に適用します。",
    sudoku_new_game: "新しい問題",
