    sudoku_rules_basics_title: "基本的な考え方",
    sudoku_term_board: "盤面",
    sudoku_rules_board: "9×9のマス目は、3×3のブロック9個に分かれています。一部のマスには最初から数字が入っていて（これを「ヒント」と呼びます）変更できません。残りのマスは空欄からスタートし、そこを埋めていきます。",
    sudoku_term_goal: "目標",
