    home_all_games_desc: "全49種類のゲームを閲覧・検索できます。アルファベット順またはタイプ別に並べ替え可能です。",
    nav_all_games: "すべてのゲーム",
    all_games_intro: "PaperGamesのすべてのゲームを一か所に。名前で検索し、アルファベット順またはタイプ別に並べ替え、星をタップしてホームページのお気に入りに追加できます。",
