    history_title: "ゲーム史ライブラリ",
    history_intro: "このコレクションのすべてのゲームには、それぞれの歴史があります。5000年以上前のものもあれば、誕生からまだ10年ほどのものもあります。ここでは各ゲームが登場したおおよその順番に読み進めることができ、気になるゲームがあればその完全な歴史ページへ直接ジャンプすることもできます。",
    history_dates_note: "最も古いゲームの年代はあくまで目安です。正確な起源は歴史の中で失われていたり、歴史家の間で議論が続いていたりします。",
