    yatzy_rules_title: "ヤッツィーのルール",
    yatzy_rules_intro: "PaperGamesでのヤッツィーの遊び方の簡単な説明です。ルールを忘れてしまった人にも、これから覚える人にも役立ちます。",
    yatzy_rules_basics_title: "基本的な流れ",
    yatzy_term_dice: "サイコロ",
    yatzy_rules_dice: "1回の手番で5個の6面サイコロを振ります。振ったあとにサイコロをタップするとそのサイコロをキープでき、キープしたサイコロは出た目のまま残ります。残りのサイコロだけをもう一度振ることができ、1回の手番につき最大3回まで振れます。",
    yatzy_term_categories: "得点表",
    yatzy_rules_categories: "その手番の最後の振りが終わったら、得点表にある15の項目のいずれかをタップして、その手のサイコロの得点を記入します。各項目はゲーム中に一度しか使えないため、良くない目でもどこかの項目に記入する必要があります。15項目すべてが埋まるとゲームは終了します。",
    yatzy_term_upper: "上段: 1の目から6の目",
    yatzy_rules_upper: "この6つの項目は、対応する目のサイコロの合計を得点にします。たとえば4の目が3個あれば、4の目の欄は12点です。6つすべてを記入し、合計で63点以上になると、追加で50点のボーナスがもらえます。",
    yatzy_term_lower: "下段: 役",
    yatzy_rules_lower: "ワンペアとツーペアは、対応するサイコロの合計を、できるだけ高い組み合わせで得点にします。フォーカードが出た場合も同じ数字のツーペアとして数えられます。スリーカードとフォーカードは、5個すべてではなく、対応する3個または4個のサイコロの合計だけを得点にします。スモールストレート（1-2-3-4-5）とラージストレート（2-3-4-5-6）は固定で15点と20点です。フルハウス（同じ数字が3個と別の数字が2個）は5個すべての合計を得点にします。チャンスは出た目に関係なく5個すべての合計を得点にします。ヤッツィー（5個すべてが同じ目）は固定で50点です。",
    yatzy_rules_end_title: "ゲームの終わり方",
    yatzy_term_total: "最終得点",
    yatzy_rules_total: "すべての項目が埋まると、最終得点は上段の合計（達成していれば50点ボーナスを含む）と下段の合計を足したものになります。対戦相手はいません。次回はあなた自身の自己ベストを目指すだけです。",

    yatzy_history_title: "ヤッツィーの歴史",
    yatzy_history_intro: "ペア、スリーカードやフォーカード、フルハウス、ストレートといった得点項目は、まさにポーカーの役そのものです。それには理由があります。",
    yatzy_history_origins_title: "ポーカーダイスから「ヨット」へ",
    yatzy_history_origins_p1: "ヤッツィーが生まれるずっと前、19世紀の「ポーカーダイス」というゲームでは、トランプの絵柄（9からエースまで）が描かれた5個のサイコロを使い、カードを一切使わずにペアやスリーカード、フルハウスといったポーカーの役を作っていました。のちに登場した「ヨット」というゲームは、普通の数字のサイコロと1回の手番での複数回の振り直しを使い、同じポーカーの役の分類を番号付きの得点表に置き換え、独自のストレートと5個同じ目の役を加えました。",
    yatzy_history_origins_p2: "よく語られる話によると、1950年代半ばに、ある夫婦が自分たちのヨット（船）の上で友人たちとこの「ヨット」というゲームを楽しみ、その記念に少数のセットを贈り物として作らせたことが、アメリカの玩具会社E.S.ローが目をつけるきっかけになったといわれています。",
    yatzy_history_spread_title: "ヤッツィーとミルトン・ブラッドリーの時代",
    yatzy_history_spread_p1: "E.S.ローは権利を取得し、1956年から「ヤッツィー」という新しい商標のもとでこのゲームを製造し始めました。ヤッツィーは20世紀で最も売れたサイコロゲームの一つとなり、E.S.ロー社自体も1973年にミルトン・ブラッドリー社に買収され、その後ミルトン・ブラッドリーは現在も「ヤッツィー」の商標を保有するハズブロの傘下に入りました。",
    yatzy_history_spread_p2: "「ヤッツィー」は登録商標であるため、同じ種類のゲームを販売・紹介したい他の出版社や地域は、通常この名称をそのまま使うことができませんでした。そのため、同じ内容の得点表が何十年もの間、さまざまな地域ごとの名前で広まっていったのです。",
    yatzy_history_modern_title: "北欧版と異なる得点表",
    yatzy_history_modern_p1: "「ヤッツィー(Yatzy)」は、この種のゲームが北欧諸国で一般的に呼ばれている名前で、単に呼び方が違うだけでなく、実際のルールにも違いがあります。北欧の得点表には、標準的なアメリカ版ヤッツィーの表にはない「ワンペア」と「ツーペア」という2つの項目が追加されており、その結果、項目数は13ではなく15項目、15ラウンドになります。",
    yatzy_history_modern_p2: "上段のボーナスも異なります。アメリカ版ヤッツィーでは1の目から6の目の合計が63点以上になると35点のボーナスが得られますが、このゲームで使われている北欧版の得点表では、同じ63点という基準に対して50点のボーナスが得られます。これは単なる地域による呼び方の違いではなく、ルール上の小さいながらも実際の違いです。",

    game_mastermind: "マスターマインド",
    home_mastermind_desc: "黒と白のピンのヒントを頼りに、限られた回数の中で4つの図形からなる隠されたコードを当てましょう。難易度によっては図形の重複が許されます。",

    mastermind_new_game: "新しいゲーム",
