    klondike_msg_cant_pick: "このカードは今は取れません。",
    klondike_msg_cant_place: "このカードはそこには置けません。",
    klondike_msg_cant_place_yet: "このカードはまだそこには置けません。",
    klondike_msg_nothing_waste: "そこにはまだ動かせるものがありません。",
    klondike_msg_stock_empty: "めくれるカードはもうありません。",
    klondike_msg_recycled: "捨て札の山から山札を作り直しました。",
    klondike_msg_undone: "手を戻しました。",
    klondike_win_title: "勝利です!",
    klondike_win_message: "4つの組札がすべて完成しました - お見事!",
    klondike_aria_stock: "山札",
    klondike_aria_waste: "捨て札",
    klondike_aria_foundation: "組札",
    klondike_aria_empty: "空",
    klondike_aria_face_down: "裏向きのカード",
    klondike_aria_tap_recycle: "タップして捨て札を山札に戻す",
    klondike_aria_up_to: "ここまで:",
    klondike_rules_title: "クロンダイクのルール",
    klondike_rules_intro: "PaperGamesでのクロンダイクの遊び方の簡単な早見表です - ルールを忘れてしまった人にも、これから覚える人にも役立ちます。",
    klondike_rules_basics_title: "基本的な考え方",
    klondike_term_layout: "配置",
    klondike_rules_layout: "カードは1枚から7枚まで、7列の場札に配られ、各列の一番上のカードだけが表向きになります。4つの組札(スート1つにつき1つ)はエースからキングまで積み上げていきます。残りのカードは山札となり、そこから1枚ずつ捨て札にめくっていきます。",
    klondike_term_tableau: "カードの移動",
    klondike_rules_tableau: "場札の列にカードを置けるのは、ちょうど1つ上のランクで色が反対のカードの上、または空いている列(キングのみ置けます)だけです。すでに表向きで同じように降順・色違いで重なっている複数枚のカードは、まとめて1つの単位として有効な移動先へ動かせます。",
    klondike_term_foundation: "組札",
    klondike_rules_foundation: "組札は自分と同じスートのカードしか受け付けず、エースから始めて1ランクずつ上がっていきます。一度組札に置かれたカードはそこにとどまり続けます - 組札はカードを受け取るだけで、場札に戻すことは決してありません。",
    klondike_term_stock: "山札と捨て札",
    klondike_rules_stock: "山札をタップすると、一番上のカードが表向きになって捨て札に移り、これを1枚ずつ行います。山札が空になった状態でもう一度タップすると、捨て札全体がシャッフルし直されて山札に戻り、再びめくり直せます - PaperGamesでは、めくり直せる回数に制限はありません。",
    klondike_rules_end_title: "ゲームの終わり方",
    klondike_term_win: "勝利",
    klondike_rules_win: "4つの組札がすべてエースからキングまで完成した瞬間にゲームに勝利します。どんな配り方でも勝てるとは限りません - FreeCellと違い、クロンダイクでは各列の一番上のカードしか最初は見えないため、ゲームの途中で本当に解けなくなることがあります。",
    klondike_history_title: "クロンダイクの歴史",
    klondike_history_intro: "数あるペイシェンスゲームの中でも最も象徴的な名前を持ち、最も広く遊ばれているゲーム - あまりに普及したため、コンピューターユーザーの数世代にとって「ソリティア」といえばこのゲーム一つを指していました。",
    klondike_history_origins_title: "ゴールドラッシュに由来する名前 - かもしれない",
    klondike_history_origins_p1: "クロンダイクは、19世紀を通じてヨーロッパと北米に広まった一人用「ペイシェンス」カードゲームの大きな系統に属し、そのほとんどは標準的なトランプ一組と平らな場所さえあれば遊べます。今日遊ばれている具体的なルール - 7列のカスケード状の場札、スートごとに積み上げる4つの組札、めくっていく山札と捨て札 - は、19世紀後半までに、地域ごとにさまざまな名前で呼ばれながらも、おおよそ現在の形に落ち着いていました。",
    klondike_history_origins_p2: "「クロンダイク」という名前が正確にどこから来たのかは、実のところはっきりしていません。最もよく語られる説では、1890年代後半のクロンダイク・ゴールドラッシュにこの名前を結び付け、ユーコンへ向かう、あるいはそこで冬を越す採掘者たちが暇つぶしにこのゲームを遊んだからだとされています。多くのカードゲームの語源がそうであるように、この色鮮やかで説得力のある由来も、記録に残る最初の使用例までたどり着いたことは一度もありません。PaperGamesではここに、確定した史実としてではなく、広く語られている説として紹介しています。",
    klondike_history_spread_title: "Windowsへの同梱",
    klondike_history_spread_p1: "今日のクロンダイクの圧倒的な人気は、19世紀のカードテーブル起源よりも、ある特定のソフトウェアによるところが大きいと言えます。マイクロソフトは1990年、単に「ソリティア」と名付けたバージョンをWindows 3.0に同梱しました - 伝えられるところによれば、新しいWindowsユーザーの世代にマウスのクリックやドラッグ操作をやんわりと教えるという狙いもあったようです。",
    klondike_history_spread_p2: "その狙いはうまくいきすぎたほどでした。わずか数年のうちに、Windowsソリティアは世界で最もよく使われるソフトウェアの一つと言われるようになり、ゲームを開くつもりがあろうとなかろうと、Windowsが入ったほぼすべてのPCにインストールされていました。それまで一度も「ソリティア」という名の物理的なトランプゲームを遊んだことのない何百万もの人々にとって、その言葉の意味そのものを作り変えたのです。",
    klondike_history_modern_title: "このバージョンについて",
    klondike_history_modern_p1: "PaperGamesでは、このコレクションのFreeCellと同じように、より手間の少ないルールを採用し、1枚ずつめくる標準的なルールで、めくり直しの回数制限もありません。毎回番号付きの決まった配り方ではなく本当に新しくシャッフルされ、山札を何度でも周回できます。",

