    // Categories (Stadt, Land, Fluss): rules and history
    categories_rules_title: "カテゴリーゲームのルール",
    categories_rules_intro: "紙とペンで遊ぶ定番の言葉遊びと、このページが進行役として行うことの簡単なまとめです。",
    categories_rules_basics_title: "基本の考え方",
    categories_term_setup: "準備",
    categories_rules_setup: "各プレイヤーは紙とペンを用意します。みんなでカテゴリーを決め(例:都市、国、川、名前、動物、職業)、紙の上部に列として書きます。このページにプレイヤーとカテゴリーを入力し、必要なら制限時間を選びます。",
    categories_term_round: "ラウンド",
    categories_rules_round: "「文字を引く」をタップします。全員が、その文字から始まる言葉を各カテゴリーに1つずつ書きます。同じ文字は1ゲームにつき1回しか出ません。",
    categories_term_stop: "ストップ",
    categories_rules_stop: "時間切れになるか、最初のプレイヤーが全カテゴリーを埋めて「ストップ!」と言ったらラウンド終了です。そのときはストップボタンをタップします。全員すぐにペンを置きます。",
    categories_rules_scoring_title: "得点",
    categories_term_points: "答えごとの得点",
    categories_rules_points: "カテゴリーごとに答えを読み上げます。自分だけの答えは10点、他の人と同じ答えは5点、そのカテゴリーで答えを見つけたのが1人だけなら20点です。答えがない、または無効な場合は0点です。表のマスをタップすると0、5、10、20の順に切り替わります。最後に「ラウンドを集計」をタップします。",
    categories_term_disputes: "判断に迷う答え",
    categories_rules_disputes: "答えが有効かどうかはみんなで決めます。迷ったら多数決です。誤字やあまりに珍しい答えを認めるかは、ゲーム前に決めておきましょう。",
    categories_term_end: "ゲームの終わり",
    categories_rules_end: "好きなだけラウンドを遊んだら「ゲーム終了」をタップします。得点が最も多い人の勝ちです。",
    categories_history_title: "カテゴリーゲームの歴史",
    categories_history_intro: "紙とペンだけで遊べる言葉遊び。国ごとに呼び名が違い、その起源は誰も書き残していません。",
    categories_history_names_title: "ひとつのゲーム、たくさんの名前",
    categories_history_names_p1: "ドイツ語圏では、3つの定番カテゴリー(都市・国・川)にちなんで「Stadt, Land, Fluss」と呼ばれます。フランスでは「Petit Bac」、イタリアでは「Nomi, cose, città」、オランダでは「Stad, land, rivier」、ポーランドでは「Państwa-miasta」、中南米の多くの地域では「Tutti Frutti」や「Basta」と呼ばれます。英語圏では単に「Categories」や「Name, Place, Animal, Thing」と呼ばれることが多いです。",
    categories_history_names_p2: "ルールの核心はどこでも同じです。ランダムな文字、カテゴリーの一覧、時計や最速のプレイヤーとの競争、そして誰も思いつかなかった答えへの得点。場所によって違うのは主にカテゴリーと文字の決め方です。",
    categories_history_origin_title: "誰も書き残さなかった起源",
    categories_history_origin_p1: "紙とペン以外に何も要らないため、このゲームは出版社ではなく、学校や家族、長旅の中で人から人へと広まりました。発明者は知られておらず、起源の年代や場所を確かに裏付ける記録もありません。それと異なる話の多くは逸話です。",
    categories_history_origin_p2: "確かなのは、多くの国で何世代にもわたって親しまれてきた娯楽であること、そして印刷されたカテゴリーカードや文字用のサイコロが入った市販の箱入り版はずっと後に登場したことです。PaperGamesは紙とペンによる伝統的な形を守り、進行役の仕事だけを引き受けます。文字を引き、時間を計り、得点を合計します。",

